"    // Save customer details on the temp table (like pickup/delivery)
    setTableCustomers(prev => ({
      ...prev,
      [tempId]: {
        customerCountryCode,
        customerPhone,
        customerName,
        customerAddress,
        selectedCustomer,
        redeemedPoints,
        appliedCoupon,
        couponCode
      }
    }));

    if (isPrint) {
      handlePrintKOT(cart, tableName, bNo);
    }

    // Clear the cart and stay on KOT tab (like pickup/delivery temp tables)
    setCart([]);
    setTableCarts(prev => ({ ...prev, [tempId]: [] }));
    setSelectedTable(newTempTable);
    toast.success(isPrint ? "KOT Printed & Saved!" : "KOT Saved!");
  };"

